def API_get_user(user_id, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0108000" if __import__("os").path.isdir("./environment_mix/0108000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "API-get-user"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _rate_limit_check(token_id):
        if not token_id:
            return None
        logs = _ensure_logs()
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs:
            if isinstance(r, dict) and r.get("auth_token_id") == token_id:
                dt = _parse_ts(r.get("timestamp") or r.get("created_at"))
                if dt and dt >= cutoff:
                    recent += 1
        if recent >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    def _log(token_id, workspace_id, status, error_code=None):
        logs = _ensure_logs()
        logs.append({
            "id": "req_" + uuid.uuid4().hex[:24],
            "endpoint": endpoint,
            "auth_token_id": token_id,
            "workspace_id": workspace_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
        })
        _save("request_logs.json", logs)

    # Vendor schema pattern is ^(usr|bot)_01H..., but datastore contains 01J...; accept either.
    if not isinstance(user_id, str) or not re.match(r"^(usr|bot)_01[0-9A-Z][0-9A-Z]+$", user_id):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "user_id is invalid.", field="user_id")

    tokens = _load("auth_tokens.json")
    users = _load("notion_users.json")
    if not isinstance(tokens, list): tokens = []
    if not isinstance(users, list): users = []

    # Ambient auth: pick any active token with a valid bot user
    token = None
    bot_user = None
    for t in tokens:
        if not isinstance(t, dict) or t.get("status") != "active":
            continue
        ws = t.get("workspace_id")
        buid = t.get("bot_user_id")
        if not isinstance(ws, str) or not isinstance(buid, str):
            continue
        u = next((r for r in users if isinstance(r, dict) and r.get("id") == buid and r.get("workspace_id") == ws), None)
        if u and u.get("type") == "bot" and u.get("status") in ("active", "deactivated"):
            token = t
            bot_user = u
            break

    if not token:
        _log(None, None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active authentication context available.")

    rl = _rate_limit_check(token.get("id"))
    if rl:
        _log(token.get("id"), token.get("workspace_id"), "error", rl["error"]["code"])
        return rl

    wsid = token.get("workspace_id")
    target = next((u for u in users if isinstance(u, dict) and u.get("id") == user_id), None)
    if not target:
        _log(token.get("id"), wsid, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "No user exists with that ID.", user_id=user_id)

    if target.get("workspace_id") != wsid:
        _log(token.get("id"), wsid, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Integration does not have access to the requested user.")

    _log(token.get("id"), wsid, "success", None)
    return {"object": "user", "user": target}

def API_get_users(limit=None, start_cursor=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0108000" if __import__("os").path.isdir("./environment_mix/0108000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(request_log, token_id, endpoint, status, started, workspace_id=None):
        latency_ms = int(max(0, (time.time() - started) * 1000))
        request_log.append(
            {
                "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "timestamp": _now(),
                "endpoint": endpoint,
                "method": "GET",
                "token_id": token_id,
                "workspace_id": workspace_id,
                "status": status,
                "latency_ms": latency_ms,
            }
        )

    started = time.time()
    endpoint = "API-get-users"

    # Validate inputs
    if limit is None:
        limit_val = 100
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 100:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100")
        limit_val = limit

    if start_cursor is not None and not isinstance(start_cursor, str):
        return _err("VALIDATION_ERROR", "start_cursor must be a string")

    auth_tokens = _load("auth_tokens.json")
    request_log = _load("request_log.json")

    # Ambient authentication: find an active token
    active_tokens = [t for t in auth_tokens if isinstance(t, dict) and t.get("status") == "active" and t.get("workspace_id")]
    if not active_tokens:
        _log(request_log, None, endpoint, 401, started, None)
        _save("request_log.json", request_log)
        return _err("UNAUTHORIZED", "Integration token missing/invalid")

    # Choose a token that actually corresponds to a valid bot user in that workspace if possible
    users = _load("notion_users.json")
    chosen = None
    for t in active_tokens:
        bot_id = t.get("bot_user_id")
        ws = t.get("workspace_id")
        bot = next((u for u in users if isinstance(u, dict) and u.get("id") == bot_id and u.get("workspace_id") == ws and u.get("type") == "bot"), None)
        if bot is not None:
            chosen = t
            break
    if chosen is None:
        chosen = active_tokens[0]

    # Update token last_used_at
    chosen["last_used_at"] = _now()
    chosen["updated_at"] = chosen.get("updated_at") or _now()
    _save("auth_tokens.json", auth_tokens)

    ws = chosen.get("workspace_id")

    # Filter to workspace + active by default
    rows = [u for u in users if isinstance(u, dict) and u.get("workspace_id") == ws and u.get("status") == "active"]

    # Stable ordering by created_at then id (best-effort)
    def _key(u):
        return (u.get("created_at") or "", u.get("id") or "")

    rows.sort(key=_key)

    # Cursoring: treat cursor as last seen user id
    start_index = 0
    if start_cursor:
        for i, u in enumerate(rows):
            if u.get("id") == start_cursor:
                start_index = i + 1
                break

    page = rows[start_index : start_index + limit_val]
    has_more = start_index + limit_val < len(rows)
    next_cursor = page[-1].get("id") if has_more and page else None

    resp = {
        "object": "list",
        "results": [{"object": "user", **u} for u in page],
        "next_cursor": next_cursor,
        "has_more": bool(has_more),
        "total": len(rows),
    }

    _log(request_log, chosen.get("id"), endpoint, 200, started, ws)
    _save("request_log.json", request_log)
    return resp

