def API_post_database_query(database_id, filter=None, sorts=None, start_cursor=None, page_size=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0108000" if __import__("os").path.isdir("./environment_mix/0108000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "API-post-database-query"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _rate_limit_check(token_id):
        if not token_id:
            return None
        logs = _ensure_logs()
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs:
            if isinstance(r, dict) and r.get("auth_token_id") == token_id:
                dt = _parse_ts(r.get("timestamp") or r.get("created_at"))
                if dt and dt >= cutoff:
                    recent += 1
        if recent >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    def _log(token_id, workspace_id, status, error_code=None):
        logs = _ensure_logs()
        logs.append({
            "id": "req_" + uuid.uuid4().hex[:24],
            "endpoint": endpoint,
            "auth_token_id": token_id,
            "workspace_id": workspace_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now()
        })
        _save("request_logs.json", logs)

    if not isinstance(database_id, str) or not re.match(r"^db_01[0-9A-Z][0-9A-Z]+$", database_id):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "database_id is invalid.", field="database_id")

    if filter is not None and not isinstance(filter, dict):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "filter must be an object.", field="filter")

    if sorts is not None:
        if not isinstance(sorts, list):
            _log(None, None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sorts must be an array.", field="sorts")
        for i, s in enumerate(sorts):
            if not isinstance(s, dict):
                _log(None, None, "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Each sort must be an object.", field=f"sorts[{i}]")
            if set(s.keys()) - {"property", "direction"}:
                _log(None, None, "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Unknown field in sort.", field=f"sorts[{i}]")
            if not isinstance(s.get("property"), str) or not s.get("property"):
                _log(None, None, "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "sort.property must be a non-empty string.", field=f"sorts[{i}].property")
            if s.get("direction") not in ("ascending", "descending"):
                _log(None, None, "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "sort.direction must be 'ascending' or 'descending'.", field=f"sorts[{i}].direction")

    if page_size is None:
        page_size = 100
    if not isinstance(page_size, int) or not (1 <= page_size <= 100):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_size must be between 1 and 100.", field="page_size")

    if start_cursor is not None and not isinstance(start_cursor, str):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "start_cursor must be a string.", field="start_cursor")

    tokens = _load("auth_tokens.json")
    users = _load("notion_users.json")
    dbs = _load("databases.json")
    pages = _load("pages.json")
    if not isinstance(tokens, list): tokens = []
    if not isinstance(users, list): users = []
    if not isinstance(dbs, list): dbs = []
    if not isinstance(pages, list): pages = []

    token = None
    for t in tokens:
        if not isinstance(t, dict) or t.get("status") != "active":
            continue
        ws = t.get("workspace_id")
        buid = t.get("bot_user_id")
        if not isinstance(ws, str) or not isinstance(buid, str):
            continue
        u = next((r for r in users if isinstance(r, dict) and r.get("id") == buid and r.get("workspace_id") == ws), None)
        if u and u.get("type") == "bot":
            token = t
            break
    if not token:
        _log(None, None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active authentication context available.")

    rl = _rate_limit_check(token.get("id"))
    if rl:
        _log(token.get("id"), token.get("workspace_id"), "error", rl["error"]["code"])
        return rl

    wsid = token.get("workspace_id")
    db = next((d for d in dbs if isinstance(d, dict) and d.get("id") == database_id and d.get("workspace_id") == wsid), None)
    if not db:
        _log(token.get("id"), wsid, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Database not found.", database_id=database_id)

    schema = db.get("properties_schema") if isinstance(db.get("properties_schema"), dict) else {}
    if sorts:
        for s in sorts:
            if s["property"] != "updated_at" and s["property"] not in schema:
                _log(token.get("id"), wsid, "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Unknown sort property.", field="sorts.property", property=s["property"])

    def _get_prop_value(page, prop_name):
        if prop_name == "updated_at":
            return page.get("updated_at")
        props = page.get("properties")
        if not isinstance(props, dict):
            return None
        v = props.get(prop_name)
        if isinstance(v, dict):
            # common Notion-ish shapes: {"type":"title","title":[...]} etc.
            if "value" in v:
                return v.get("value")
            if "name" in v:
                return v.get("name")
            if "title" in v and isinstance(v.get("title"), list):
                # concatenate plain_text if present, else stringify
                parts = []
                for rt in v["title"]:
                    if isinstance(rt, dict):
                        pt = rt.get("plain_text")
                        if isinstance(pt, str):
                            parts.append(pt)
                if parts:
                    return "".join(parts)
                return json.dumps(v["title"], ensure_ascii=False)
            if "rich_text" in v and isinstance(v.get("rich_text"), list):
                parts = []
                for rt in v["rich_text"]:
                    if isinstance(rt, dict) and isinstance(rt.get("plain_text"), str):
                        parts.append(rt["plain_text"])
                if parts:
                    return "".join(parts)
                return json.dumps(v["rich_text"], ensure_ascii=False)
            if "number" in v:
                return v.get("number")
            if "checkbox" in v:
                return v.get("checkbox")
            if "select" in v and isinstance(v.get("select"), dict):
                return v["select"].get("name")
        return v

    def _matches_simple_filter(page, fobj):
        # Minimal implementation: supports {property, equals} / {property, contains} / compound {and:[]}/{or:[]}
        if not isinstance(fobj, dict) or not fobj:
            return True
        if "and" in fobj:
            arr = fobj.get("and")
            if not isinstance(arr, list):
                return False
            return all(_matches_simple_filter(page, x) for x in arr)
        if "or" in fobj:
            arr = fobj.get("or")
            if not isinstance(arr, list):
                return False
            return any(_matches_simple_filter(page, x) for x in arr)
        prop = fobj.get("property")
        if not isinstance(prop, str) or not prop:
            return False
        if prop != "updated_at" and prop not in schema:
            return False
        pv = _get_prop_value(page, prop)
        if "equals" in fobj:
            return pv == fobj.get("equals")
        if "contains" in fobj:
            needle = fobj.get("contains")
            if not isinstance(needle, str):
                return False
            return needle.lower() in ("" if pv is None else str(pv)).lower()
        # if unknown operator, treat as malformed
        return False

    rows = []
    for p in pages:
        if not isinstance(p, dict):
            continue
        if p.get("workspace_id") != wsid:
            continue
        if p.get("parent_type") != "database" or p.get("parent_database_id") != database_id:
            continue
        # exclude trashed by default
        if p.get("status") == "trashed" or p.get("trashed") is True:
            continue
        if filter is not None and not _matches_simple_filter(p, filter):
            continue
        rows.append(p)

    # sorts
    if sorts:
        for s in reversed(sorts):
            key = s["property"]
            rev = (s["direction"] == "descending")
            rows.sort(key=lambda pg: ("" if _get_prop_value(pg, key) is None else str(_get_prop_value(pg, key))), reverse=rev)
    else:
        # default: updated_at desc like many list endpoints
        rows.sort(key=lambda pg: pg.get("updated_at") or "", reverse=True)

    # pagination via cursor = page id
    start_index = 0
    if start_cursor:
        for i, r in enumerate(rows):
            if r.get("id") == start_cursor:
                start_index = i + 1
                break

    page_rows = rows[start_index:start_index + page_size]
    has_more = (start_index + page_size) < len(rows)
    next_cursor = page_rows[-1].get("id") if (has_more and page_rows) else None

    _log(token.get("id"), wsid, "success", None)
    return {
        "object": "list",
        "results": page_rows,
        "next_cursor": next_cursor,
        "has_more": has_more,
        "total": len(rows)
    }

