        recent = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("auth_token_id") != token_id:
                continue
            ts = r.get("timestamp") or r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                recent += 1
        if recent >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    if page_size is None:
        page_size = 100
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_size must be between 1 and 100.", field="page_size")
    if start_cursor is not None and not isinstance(start_cursor, str):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "start_cursor must be a string.", field="start_cursor")

    if query is not None and not isinstance(query, str):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query must be a string.", field="query")

    if sort is not None:
        if not isinstance(sort, dict) or set(sort.keys()) != {"direction", "timestamp"}:
            _log(None, None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sort must be an object with direction and timestamp.", field="sort")
        if sort.get("direction") not in ("ascending", "descending") or sort.get("timestamp") != "last_edited_time":
            _log(None, None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Unsupported sort configuration.", field="sort")

    obj_filter = None
    if filter is not None:
        if not isinstance(filter, dict) or set(filter.keys()) != {"property", "value"}:
            _log(None, None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "filter must be an object with property and value.", field="filter")
        if filter.get("property") != "object" or filter.get("value") not in ("page", "database"):
            _log(None, None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Unsupported filter configuration.", field="filter")
        obj_filter = filter.get("value")

    tokens = _load("auth_tokens.json")
    if not isinstance(tokens, list): tokens = []
    token = next((t for t in tokens if isinstance(t, dict) and t.get("status") == "active" and isinstance(t.get("workspace_id"), str)), None)
    if token is None:
        _log(None, None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Integration token missing or invalid.")

    rl = _check_rate_limit(token.get("id"))
    if rl:
        _log(token.get("id"), token.get("workspace_id"), "error", rl["error"]["code"])
        return rl

    now = _now()
    changed = False
    for t in tokens:
        if isinstance(t, dict) and t.get("id") == token.get("id"):
            t["last_used_at"] = now
            t["updated_at"] = now
            changed = True
            break
    if changed:
        _save("auth_tokens.json", tokens)

    wsid = token.get("workspace_id")

    pages = _load("pages.json")
    dbs = _load("databases.json")
    if not isinstance(pages, list): pages = []
    if not isinstance(dbs, list): dbs = []

    q = (query or "").strip().lower()

    def _textify(v):
        if v is None:
            return ""
        if isinstance(v, str):
            return v
        if isinstance(v, (int, float, bool)):
            return str(v)
        if isinstance(v, list):
            return " ".join(_textify(x) for x in v)
        if isinstance(v, dict):
            if "name" in v and isinstance(v.get("name"), str):
                return v.get("name")
            for k in ("plain_text", "content", "title", "rich_text", "text"):
                if k in v:
                    return _textify(v.get(k))
            return " ".join(_textify(x) for x in v.values())
        return ""

    def _page_index_text(p):
        props = p.get("properties")
        if not isinstance(props, dict):
            return ""
        # best-effort: combine all property values
        return " ".join(_textify(v) for v in props.values())

    def _db_index_text(d):
        return _textify(d.get("title")) + " " + _textify(d.get("description"))

    results = []

    if obj_filter in (None, "page"):
        for p in pages:
            if not isinstance(p, dict) or p.get("workspace_id") != wsid:
                continue
            if p.get("status") == "trashed":
                continue
            text = _page_index_text(p).lower()
            if q and q not in text and q not in (p.get("id") or "").lower() and q not in (p.get("url") or "").lower():
                continue
            results.append({
                "object": "search_result",
                "type": "page",
                "page": p,
                "_ts": p.get("updated_at") or ""
            })

    if obj_filter in (None, "database"):
        for d in dbs:
            if not isinstance(d, dict) or d.get("workspace_id") != wsid:
                continue
            # archived databases are still searchable; but keep them in results (notion includes them sometimes)
            text = _db_index_text(d).lower()
            if q and q not in text and q not in (d.get("id") or "").lower():
                continue
            results.append({
                "object": "search_result",
                "type": "database",
                "database": d,
                "_ts": d.get("updated_at") or ""
            })

    # sort
    direction = (sort or {}).get("direction") if sort else "descending"
    reverse = (direction == "descending")
    results.sort(key=lambda r: r.get("_ts") or "", reverse=reverse)

    total = len(results)

    # pagination (start_cursor is an id of underlying object)
    start_index = 0
    if start_cursor:
        for i, r in enumerate(results):
            obj = r.get("page") if r.get("type") == "page" else r.get("database")
            if isinstance(obj, dict) and obj.get("id") == start_cursor:
                start_index = i + 1
                break

    page_results = results[start_index:start_index + page_size]
    has_more = (start_index + page_size) < len(results)
    next_cursor = None
    if has_more and page_results:
        last = page_results[-1]
        obj = last.get("page") if last.get("type") == "page" else last.get("database")
        next_cursor = obj.get("id") if isinstance(obj, dict) else None

    # strip internal
    for r in page_results:
        if "_ts" in r:
            del r["_ts"]

    _log(token.get("id"), wsid, "success", None)
    return {"object": "list", "results": page_results, "total": total, "has_more": has_more, "next_cursor": next_cursor}

def API_get_block_children(block_id, start_cursor=None, page_size=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0108000" if __import__("os").path.isdir("./environment_mix/0108000") else "/app/database")
    def _load(n):
