    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "API-get-block-children"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _rate_limit_check(token_id):
        if not token_id:
            return None
        logs = _ensure_logs()
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs:
            if isinstance(r, dict) and r.get("auth_token_id") == token_id:
                dt = _parse_ts(r.get("timestamp") or r.get("created_at"))
                if dt and dt >= cutoff:
                    recent += 1
        if recent >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    def _log(token_id, workspace_id, status, error_code=None):
        logs = _ensure_logs()
        logs.append({
            "id": "req_" + uuid.uuid4().hex[:24],
            "endpoint": endpoint,
            "auth_token_id": token_id,
            "workspace_id": workspace_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now()
        })
        _save("request_logs.json", logs)

    if not isinstance(block_id, str) or not re.match(r"^blk_01[0-9A-Z][0-9A-Z]+$", block_id):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "block_id is invalid.", field="block_id")

    if page_size is None:
        page_size = 100
    if not isinstance(page_size, int) or not (1 <= page_size <= 100):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_size must be between 1 and 100.", field="page_size")

    if start_cursor is not None and not isinstance(start_cursor, str):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "start_cursor must be a string.", field="start_cursor")

    tokens = _load("auth_tokens.json")
    users = _load("notion_users.json")
    blocks = _load("blocks.json")
    if not isinstance(tokens, list): tokens = []
    if not isinstance(users, list): users = []
    if not isinstance(blocks, list): blocks = []

    token = None
    for t in tokens:
        if not isinstance(t, dict) or t.get("status") != "active":
            continue
        ws = t.get("workspace_id")
        buid = t.get("bot_user_id")
        if not isinstance(ws, str) or not isinstance(buid, str):
            continue
        u = next((r for r in users if isinstance(r, dict) and r.get("id") == buid and r.get("workspace_id") == ws), None)
        if u and u.get("type") == "bot":
            token = t
            break
    if not token:
        _log(None, None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active authentication context available.")

    rl = _rate_limit_check(token.get("id"))
    if rl:
        _log(token.get("id"), token.get("workspace_id"), "error", rl["error"]["code"])
        return rl

    wsid = token.get("workspace_id")
    parent = next((b for b in blocks if isinstance(b, dict) and b.get("id") == block_id and b.get("workspace_id") == wsid), None)
    if not parent:
        _log(token.get("id"), wsid, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Parent block does not exist.", block_id=block_id)

    children_all = []
    for b in blocks:
        if not isinstance(b, dict):
            continue
        if b.get("workspace_id") != wsid:
            continue
        if b.get("parent_block_id") != block_id:
            continue
        if b.get("archived") is True or b.get("status") == "archived":
            continue
        children_all.append(b)

    children_all.sort(key=lambda x: (x.get("children_sort") if isinstance(x.get("children_sort"), int) else 0, x.get("created_at") or ""))

    start_index = 0
    if start_cursor:
        for i, r in enumerate(children_all):
            if r.get("id") == start_cursor:
                start_index = i + 1
                break

    page_rows = children_all[start_index:start_index + page_size]
    has_more = (start_index + page_size) < len(children_all)
    next_cursor = page_rows[-1].get("id") if (has_more and page_rows) else None

    _log(token.get("id"), wsid, "success", None)
    return {"object": "list", "results": page_rows, "next_cursor": next_cursor, "has_more": has_more, "total": len(children_all)}

def API_patch_block_children(block_id, children, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0108000" if __import__("os").path.isdir("./environment_mix/0108000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "API-patch-block-children"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _rate_limit_check(token_id):
        if not token_id:
            return None
        logs = _ensure_logs()
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs:
            if isinstance(r, dict) and r.get("auth_token_id") == token_id:
                dt = _parse_ts(r.get("timestamp") or r.get("created_at"))
                if dt and dt >= cutoff:
                    recent += 1
        if recent >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    def _log(token_id, workspace_id, status, error_code=None):
        logs = _ensure_logs()
        logs.append({
            "id": "req_" + uuid.uuid4().hex[:24],
            "endpoint": endpoint,
            "auth_token_id": token_id,
            "workspace_id": workspace_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now()
        })
        _save("request_logs.json", logs)

    allowed_types = {
        "paragraph", "heading_1", "heading_2", "heading_3",
        "bulleted_list_item", "numbered_list_item", "to_do", "toggle",
        "code", "quote", "callout", "divider", "image", "bookmark",
        "table", "table_row", "child_page", "child_database",
        "synced_block", "template", "unsupported"
    }

    if not isinstance(block_id, str) or not re.match(r"^blk_01[0-9A-Z][0-9A-Z]+$", block_id):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "block_id is invalid.", field="block_id")

    if not isinstance(children, list) or len(children) < 1:
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "children must be a non-empty array.", field="children")

    for i, ch in enumerate(children):
        if not isinstance(ch, dict):
            _log(None, None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Each child must be an object.", field=f"children[{i}]")
        if set(ch.keys()) - {"type", "content"}:
            _log(None, None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Child contains unknown fields.", field=f"children[{i}]")
        if ch.get("type") not in allowed_types:
            _log(None, None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Unsupported block type.", field=f"children[{i}].type")
        if not isinstance(ch.get("content"), dict):
            _log(None, None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "content must be an object.", field=f"children[{i}].content")

    tokens = _load("auth_tokens.json")
    users = _load("notion_users.json")
    blocks = _load("blocks.json")
    pages = _load("pages.json")
    if not isinstance(tokens, list): tokens = []
    if not isinstance(users, list): users = []
    if not isinstance(blocks, list): blocks = []
    if not isinstance(pages, list): pages = []

    token = None
    bot_user = None
    for t in tokens:
        if not isinstance(t, dict) or t.get("status") != "active":
            continue
        ws = t.get("workspace_id")
        buid = t.get("bot_user_id")
        if not isinstance(ws, str) or not isinstance(buid, str):
            continue
        u = next((r for r in users if isinstance(r, dict) and r.get("id") == buid and r.get("workspace_id") == ws), None)
        if u and u.get("type") == "bot":
            token = t
            bot_user = u
            break
    if not token:
        _log(None, None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active authentication context available.")

    rl = _rate_limit_check(token.get("id"))
    if rl:
        _log(token.get("id"), token.get("workspace_id"), "error", rl["error"]["code"])
        return rl

    wsid = token.get("workspace_id")
    parent = next((b for b in blocks if isinstance(b, dict) and b.get("id") == block_id and b.get("workspace_id") == wsid), None)
    if not parent:
        _log(token.get("id"), wsid, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Parent block does not exist.", block_id=block_id)

    # Parent must not be archived to append
    if parent.get("archived") is True or parent.get("status") == "archived":
        _log(token.get("id"), wsid, "error", "CONFLICT")
        return _err("CONFLICT", "Cannot append children to an archived block.", block_id=block_id)

    # Validate parent page exists and not trashed (content writes)
    page_id = parent.get("page_id")
    if not isinstance(page_id, str):
        _log(token.get("id"), wsid, "error", "CONFLICT")
        return _err("CONFLICT", "Parent block is missing page context.", block_id=block_id)
    page = next((p for p in pages if isinstance(p, dict) and p.get("id") == page_id and p.get("workspace_id") == wsid), None)
    if not page:
        _log(token.get("id"), wsid, "error", "CONFLICT")
        return _err("CONFLICT", "Parent block page does not exist.", page_id=page_id)
    if page.get("status") == "trashed" or page.get("trashed") is True:
        _log(token.get("id"), wsid, "error", "CONFLICT")
        return _err("CONFLICT", "Cannot modify blocks on a trashed page.", page_id=page_id)

    # Determine next children_sort
    max_sort = -1
    for b in blocks:
        if isinstance(b, dict) and b.get("workspace_id") == wsid and b.get("parent_block_id") == block_id:
            cs = b.get("children_sort")
            if isinstance(cs, int) and cs > max_sort:
                max_sort = cs
    next_sort = max_sort + 1

    now = _now()

    def _new_id(prefix):
        return prefix + "_" + uuid.uuid4().hex[:24]

    new_rows = []
    for ch in children:
        bid = _new_id("blk")
        row = {
            "id": bid,
            "workspace_id": wsid,
            "page_id": page_id,
            "parent_block_id": block_id,
            "type": ch["type"],
            "content": ch["content"],
            "has_children": False,
            "children_sort": next_sort,
            "archived": False,
            "status": "active",
            "created_by_user_id": bot_user.get("id") if bot_user else parent.get("created_by_user_id"),
            "last_edited_by_user_id": bot_user.get("id") if bot_user else parent.get("last_edited_by_user_id"),
            "created_at": now,
            "updated_at": now,
        }
        next_sort += 1
        blocks.append(row)
        new_rows.append(row)

    # Atomically set parent.has_children=true when at least one active child exists
    active_child_exists = any(
        isinstance(b, dict) and b.get("workspace_id") == wsid and b.get("parent_block_id") == block_id and b.get("status") == "active" and b.get("archived") is not True
        for b in blocks
    )
    if active_child_exists:
        for b in blocks:
            if isinstance(b, dict) and b.get("id") == block_id and b.get("workspace_id") == wsid:
                b["has_children"] = True
                b["last_edited_by_user_id"] = bot_user.get("id") if bot_user else b.get("last_edited_by_user_id")
                b["updated_at"] = now
                break

    _save("blocks.json", blocks)

    # Return updated listing of children including new ones, sorted
    children_all = [b for b in blocks if isinstance(b, dict) and b.get("workspace_id") == wsid and b.get("parent_block_id") == block_id and b.get("archived") is not True and b.get("status") == "active"]
    children_all.sort(key=lambda x: (x.get("children_sort") if isinstance(x.get("children_sort"), int) else 0, x.get("created_at") or ""))

    _log(token.get("id"), wsid, "success", None)
    return {"object": "list", "results": children_all, "next_cursor": None, "has_more": False, "total": len(children_all)}

