        return _err("UNAUTHORIZED", "No active authentication context available.")

    rl = _rate_limit_check(token.get("id"))
    if rl:
        _log(token.get("id"), token.get("workspace_id"), "error", rl["error"]["code"])
        return rl

    wsid = token.get("workspace_id")
    blk = next((b for b in blocks if isinstance(b, dict) and b.get("id") == block_id and b.get("workspace_id") == wsid), None)
    if not blk:
        _log(token.get("id"), wsid, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "No block exists with that ID.", block_id=block_id)

    _log(token.get("id"), wsid, "success", None)
    return {"object": "block", "block": blk}

def API_update_a_block(block_id, archived=None, content=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0108000" if __import__("os").path.isdir("./environment_mix/0108000") else "/app/database")
    def _load(n):
