    if not token:
        # log attempt if possible
        reqlog = _load("request_logs.json")
        if isinstance(reqlog, list):
            reqlog.append({"id": f"req_{int(time.time()*1000)}", "endpoint": "API-update-a-block", "status": "UNAUTHORIZED", "timestamp": now, "latency_ms": int((time.time()-t0)*1000), "auth_token_id": None})
            _save("request_logs.json", reqlog)
        return _err("UNAUTHORIZED", "No active authentication token available.")
    wsid = token["workspace_id"]

    # rate/quota if present
    reqlog = _load("request_logs.json")
    if isinstance(reqlog, list):
        window_s = 60
        limit = 120
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
        recent = 0
        for r in reqlog:
            if not isinstance(r, dict): 
                continue
            if r.get("auth_token_id") != token.get("id"):
                continue
            ts = r.get("timestamp")
            if isinstance(ts, str):
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                    if dt >= cutoff:
                        recent += 1
                except Exception:
                    pass
        if recent >= limit:
            reqlog.append({"id": f"req_{int(time.time()*1000)}", "endpoint": "API-update-a-block", "status": "RATE_LIMIT", "timestamp": now, "latency_ms": int((time.time()-t0)*1000), "auth_token_id": token.get("id")})
            _save("request_logs.json", reqlog)
            return _err("RATE_LIMIT", "Rate limit exceeded.")
    # --- Validate inputs ---
    if not isinstance(block_id, str) or not re.match(r"^blk_01H[0-9A-Z]+$", block_id):
        status = "VALIDATION_ERROR"
        if isinstance(reqlog, list):
            reqlog.append({"id": f"req_{int(time.time()*1000)}", "endpoint": "API-update-a-block", "status": status, "timestamp": now, "latency_ms": int((time.time()-t0)*1000), "auth_token_id": token.get("id")})
            _save("request_logs.json", reqlog)
        return _err("VALIDATION_ERROR", "block_id is invalid.", field="block_id")

    if archived is None and content is None:
        status = "VALIDATION_ERROR"
        if isinstance(reqlog, list):
            reqlog.append({"id": f"req_{int(time.time()*1000)}", "endpoint": "API-update-a-block", "status": status, "timestamp": now, "latency_ms": int((time.time()-t0)*1000), "auth_token_id": token.get("id")})
            _save("request_logs.json", reqlog)
        return _err("VALIDATION_ERROR", "No updatable fields provided. Provide at least one of archived or content.")

    if archived is not None and not isinstance(archived, bool):
        status = "VALIDATION_ERROR"
        if isinstance(reqlog, list):
            reqlog.append({"id": f"req_{int(time.time()*1000)}", "endpoint": "API-update-a-block", "status": status, "timestamp": now, "latency_ms": int((time.time()-t0)*1000), "auth_token_id": token.get("id")})
            _save("request_logs.json", reqlog)
        return _err("VALIDATION_ERROR", "archived must be a boolean.", field="archived")

    if content is not None and not isinstance(content, dict):
        status = "VALIDATION_ERROR"
        if isinstance(reqlog, list):
            reqlog.append({"id": f"req_{int(time.time()*1000)}", "endpoint": "API-update-a-block", "status": status, "timestamp": now, "latency_ms": int((time.time()-t0)*1000), "auth_token_id": token.get("id")})
            _save("request_logs.json", reqlog)
        return _err("VALIDATION_ERROR", "content must be an object.", field="content")

    # --- Load and authorize block ---
    blocks = _load("blocks.json")
    blk = None
    idx = None
    for i, b in enumerate(blocks):
        if isinstance(b, dict) and b.get("id") == block_id:
            blk = b
            idx = i
            break
    if not blk or blk.get("workspace_id") != wsid:
        status = "NOT_FOUND"
        if isinstance(reqlog, list):
            reqlog.append({"id": f"req_{int(time.time()*1000)}", "endpoint": "API-update-a-block", "status": status, "timestamp": now, "latency_ms": int((time.time()-t0)*1000), "auth_token_id": token.get("id")})
            _save("request_logs.json", reqlog)
        return _err("NOT_FOUND", "Block not found.")

    # --- Basic permission model based on scopes (if present) ---
    scopes = token.get("scopes")
    if isinstance(scopes, list):
        has_write = any(isinstance(s, str) and ("write" in s or s.endswith(":write")) for s in scopes) or ("write" in scopes)
        if not has_write:
            status = "UNAUTHORIZED"
            if isinstance(reqlog, list):
                reqlog.append({"id": f"req_{int(time.time()*1000)}", "endpoint": "API-update-a-block", "status": status, "timestamp": now, "latency_ms": int((time.time()-t0)*1000), "auth_token_id": token.get("id")})
                _save("request_logs.json", reqlog)
            return _err("UNAUTHORIZED", "Token does not have permission to update blocks.")

    # --- Enforce Notion semantics: type cannot change; content must be compatible ---
    blk_type = blk.get("type")
    if not isinstance(blk_type, str):
        return _err("CONFLICT", "Block has invalid type in datastore.")
    if content is not None:
        # If payload tries to declare a different type, reject
        if "type" in content and content.get("type") != blk_type:
            status = "VALIDATION_ERROR"
            if isinstance(reqlog, list):
                reqlog.append({"id": f"req_{int(time.time()*1000)}", "endpoint": "API-update-a-block", "status": status, "timestamp": now, "latency_ms": int((time.time()-t0)*1000), "auth_token_id": token.get("id")})
                _save("request_logs.json", reqlog)
            return _err("VALIDATION_ERROR", "Block type cannot be changed after creation.", field="content.type")
        # Content must be an object; optionally allow either full replacement or partial merge.
        existing_content = blk.get("content")
        if existing_content is None:
            existing_content = {}
        if not isinstance(existing_content, dict):
            existing_content = {}
        # Minimal compatibility check: if content has a key matching block type, it must be an object/array depending on common shapes
        # We won't enforce deep Notion schema, but we do enforce that it is JSON-like.
        for k, v in content.items():
            # disallow attempts to set foreign keys / immutable fields via content
            if k in ("id", "workspace_id", "page_id", "parent_block_id", "children_sort", "created_at", "created_by_user_id"):
                status = "VALIDATION_ERROR"
                if isinstance(reqlog, list):
                    reqlog.append({"id": f"req_{int(time.time()*1000)}", "endpoint": "API-update-a-block", "status": status, "timestamp": now, "latency_ms": int((time.time()-t0)*1000), "auth_token_id": token.get("id")})
                    _save("request_logs.json", reqlog)
                return _err("VALIDATION_ERROR", f"Field '{k}' is not updatable via content.", field=f"content.{k}")
            # accept scalars/arrays/objects; reject non-JSON types
            if isinstance(v, (str, int, float, bool)) or v is None or isinstance(v, list) or isinstance(v, dict):
                continue
            status = "VALIDATION_ERROR"
            if isinstance(reqlog, list):
                reqlog.append({"id": f"req_{int(time.time()*1000)}", "endpoint": "API-update-a-block", "status": status, "timestamp": now, "latency_ms": int((time.time()-t0)*1000), "auth_token_id": token.get("id")})
                _save("request_logs.json", reqlog)
            return _err("VALIDATION_ERROR", "content contains a value that is not JSON-serializable.", field=f"content.{k}")

        # merge update
        existing_content.update(content)
        blk["content"] = existing_content

    # archived/state transition
    if archived is not None:
        old_status = blk.get("status")
        if archived is True:
            # active -> archived allowed
            if old_status not in ("active", "archived"):
                return _err("CONFLICT", "Block has invalid status in datastore.")
            # idempotent if already archived
            blk["archived"] = True
            blk["status"] = "archived"
        else:
            # unarchive: archived -> active allowed
            if old_status not in ("active", "archived"):
                return _err("CONFLICT", "Block has invalid status in datastore.")
            blk["archived"] = False
            blk["status"] = "active"

    # Update audit fields
    bot_user_id = token.get("bot_user_id")
    if isinstance(bot_user_id, str) and bot_user_id:
        blk["last_edited_by_user_id"] = bot_user_id
    blk["updated_at"] = now

    blocks[idx] = blk
    _save("blocks.json", blocks)

    # Update token last_used_at
    for i, t in enumerate(tokens):
        if isinstance(t, dict) and t.get("id") == token.get("id"):
            t["last_used_at"] = now
            t["updated_at"] = t.get("updated_at") or now
            tokens[i] = t
            _save("auth_tokens.json", tokens)
            break

    status = "OK"
    if isinstance(reqlog, list):
        reqlog.append({"id": f"req_{int(time.time()*1000)}", "endpoint": "API-update-a-block", "status": status, "timestamp": now, "latency_ms": int((time.time()-t0)*1000), "auth_token_id": token.get("id")})
        _save("request_logs.json", reqlog)

    return {"object": "block", "data": blk}

def API_delete_a_block(block_id, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0108000" if __import__("os").path.isdir("./environment_mix/0108000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "API-delete-a-block"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _rate_limit_check(token_id):
        if not token_id:
            return None
        logs = _ensure_logs()
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs:
            if isinstance(r, dict) and r.get("auth_token_id") == token_id:
                dt = _parse_ts(r.get("timestamp") or r.get("created_at"))
                if dt and dt >= cutoff:
                    recent += 1
        if recent >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    def _log(token_id, workspace_id, status, error_code=None):
        logs = _ensure_logs()
        logs.append({
            "id": "req_" + uuid.uuid4().hex[:24],
            "endpoint": endpoint,
            "auth_token_id": token_id,
            "workspace_id": workspace_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
        })
        _save("request_logs.json", logs)

    if not isinstance(block_id, str) or not re.match(r"^blk_01[0-9A-Z][0-9A-Z]+$", block_id):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "block_id is invalid.", field="block_id")

    tokens = _load("auth_tokens.json")
    users = _load("notion_users.json")
    blocks = _load("blocks.json")
    if not isinstance(tokens, list): tokens = []
    if not isinstance(users, list): users = []
    if not isinstance(blocks, list): blocks = []

    token = None
    bot_user = None
    for t in tokens:
        if not isinstance(t, dict) or t.get("status") != "active":
            continue
        ws = t.get("workspace_id")
        buid = t.get("bot_user_id")
        if not isinstance(ws, str) or not isinstance(buid, str):
            continue
        u = next((r for r in users if isinstance(r, dict) and r.get("id") == buid and r.get("workspace_id") == ws), None)
        if u and u.get("type") == "bot":
            token = t
            bot_user = u
            break
    if not token:
        _log(None, None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active authentication context available.")

    rl = _rate_limit_check(token.get("id"))
    if rl:
        _log(token.get("id"), token.get("workspace_id"), "error", rl["error"]["code"])
        return rl

    wsid = token.get("workspace_id")
    blk = next((b for b in blocks if isinstance(b, dict) and b.get("id") == block_id and b.get("workspace_id") == wsid), None)
    if not blk:
        _log(token.get("id"), wsid, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Block does not exist.", block_id=block_id)

    # Idempotent-ish: if already archived, return it
    if blk.get("archived") is True and blk.get("status") == "archived":
        _log(token.get("id"), wsid, "success", None)
        return {"object": "block", "block": blk}

    # Transition active -> archived only
    if blk.get("status") not in ("active", "archived"):
        _log(token.get("id"), wsid, "error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Block is in an invalid lifecycle state.", status=blk.get("status"))

    if blk.get("status") == "archived":
        # archived=false but status=archived etc. normalize
        blk["archived"] = True
        blk["status"] = "archived"
        blk["updated_at"] = _now()
        blk["last_edited_by_user_id"] = bot_user.get("id") if bot_user else blk.get("last_edited_by_user_id")
        _save("blocks.json", blocks)
        _log(token.get("id"), wsid, "success", None)
        return {"object": "block", "block": blk}

    now = _now()
    # apply archive
    for b in blocks:
        if isinstance(b, dict) and b.get("id") == block_id and b.get("workspace_id") == wsid:
            b["archived"] = True
            b["status"] = "archived"
            b["updated_at"] = now
            b["last_edited_by_user_id"] = bot_user.get("id") if bot_user else b.get("last_edited_by_user_id")
            blk = b
            break

    # Update parent.has_children when no active children remain
    parent_id = blk.get("parent_block_id")
    if isinstance(parent_id, str):
        active_left = any(
            isinstance(x, dict) and x.get("workspace_id") == wsid and x.get("parent_block_id") == parent_id and x.get("status") == "active" and x.get("archived") is not True
            for x in blocks
        )
        if not active_left:
            for pb in blocks:
                if isinstance(pb, dict) and pb.get("id") == parent_id and pb.get("workspace_id") == wsid:
                    pb["has_children"] = False
                    pb["updated_at"] = now
                    pb["last_edited_by_user_id"] = bot_user.get("id") if bot_user else pb.get("last_edited_by_user_id")
                    break

    _save("blocks.json", blocks)
    _log(token.get("id"), wsid, "success", None)
    return {"object": "block", "block": blk}

