        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_id is malformed.", field="page_id")

    if properties is not None and not isinstance(properties, dict):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "properties must be an object.", field="properties")
    if icon is not None and not isinstance(icon, dict):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "icon must be an object.", field="icon")
    if cover is not None and not isinstance(cover, dict):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cover must be an object.", field="cover")
    if archived is not None and not isinstance(archived, bool):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "archived must be a boolean.", field="archived")
    if trashed is not None and not isinstance(trashed, bool):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "trashed must be a boolean.", field="trashed")

    # Mutually incompatible? In Notion you can set both, but status must reflect; if both true -> trashed wins.
    tokens = _load("auth_tokens.json")
    users = _load("notion_users.json")
    pages = _load("pages.json")
    dbs = _load("databases.json")
    if not isinstance(tokens, list): tokens = []
    if not isinstance(users, list): users = []
    if not isinstance(pages, list): pages = []
    if not isinstance(dbs, list): dbs = []
    token = None
    bot_user = None
    for t in tokens:
        if not isinstance(t, dict) or t.get("status") != "active":
            continue
        ws = t.get("workspace_id")
        buid = t.get("bot_user_id")
        if not isinstance(ws, str) or not isinstance(buid, str):
            continue
        u = next((r for r in users if isinstance(r, dict) and r.get("id") == buid and r.get("workspace_id") == ws), None)
        if u and u.get("type") == "bot":
            token = t
            bot_user = u
            break
    if not token:
        _log(None, None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active authentication context available.")

    rl = _rate_limit_check(token.get("id"))
    if rl:
        _log(token.get("id"), token.get("workspace_id"), "error", rl["error"]["code"])
        return rl

    wsid = token.get("workspace_id")
    page = next((p for p in pages if isinstance(p, dict) and p.get("id") == page_id and p.get("workspace_id") == wsid), None)
    if not page:
        _log(token.get("id"), wsid, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Page does not exist.", page_id=page_id)

    # If parent is a database, validate properties against schema minimally: known keys only + required keys if specified
    parent_db_id = page.get("parent_database_id") if page.get("parent_type") == "database" else None
    db_schema = None
    if isinstance(parent_db_id, str):
        db = next((d for d in dbs if isinstance(d, dict) and d.get("id") == parent_db_id and d.get("workspace_id") == wsid), None)
        if db and isinstance(db.get("properties_schema"), dict):
            db_schema = db["properties_schema"]

    if properties is not None and isinstance(db_schema, dict):
        for k in properties.keys():
            if k not in db_schema:
                _log(token.get("id"), wsid, "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Unknown property for this database schema.", field="properties", property=k)

    now = _now()
    changed = False
    for i, p in enumerate(pages):
        if not isinstance(p, dict) or p.get("id") != page_id or p.get("workspace_id") != wsid:
            continue
        if properties is not None:
            if not isinstance(p.get("properties"), dict):
                p["properties"] = {}
            p["properties"].update(properties)
            changed = True
        if icon is not None:
            p["icon"] = icon
            changed = True
        if cover is not None:
            p["cover"] = cover
            changed = True
        if archived is not None:
            p["archived"] = archived
            changed = True
        if trashed is not None:
            p["trashed"] = trashed
            changed = True

        # derive status consistent with flags; trashed wins over archived
        arch_flag = bool(p.get("archived"))
        trash_flag = bool(p.get("trashed"))
        old_status = p.get("status")
        new_status = "active"
        if trash_flag:
            new_status = "trashed"
        elif arch_flag:
            new_status = "archived"

        # enforce lifecycle transitions
        transitions = {
            "active": {"archived", "trashed"},
            "archived": {"active", "trashed"},
            "trashed": {"active"}
        }
        if old_status in transitions and new_status != old_status:
            if new_status not in transitions[old_status]:
                _log(token.get("id"), wsid, "error", "INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", "Illegal page status transition.", from_status=old_status, to_status=new_status)
        elif old_status not in transitions:
            _log(token.get("id"), wsid, "error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Page has an invalid lifecycle state.", status=old_status)

        if new_status != old_status:
            p["status"] = new_status
            changed = True

        if changed:
            p["last_edited_by_user_id"] = bot_user.get("id") if bot_user else p.get("last_edited_by_user_id")
            p["updated_at"] = now

        page = p
        pages[i] = p
        break

    if not changed:
        # no-op is allowed? Notion would return current page but mutation without effect violates contract
        _log(token.get("id"), wsid, "error", "CONFLICT")
        return _err("CONFLICT", "No updates were provided.")

    _save("pages.json", pages)
    _log(token.get("id"), wsid, "success", None)
    return {"object": "page", "page": page}

def API_post_page(parent, properties, icon=None, cover=None, children=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0108000" if __import__("os").path.isdir("./environment_mix/0108000") else "/app/database")
    def _load(n):
