    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "API-post-page"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _rate_limit_check(token_id):
        if not token_id:
            return None
        logs = _ensure_logs()
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs:
            if isinstance(r, dict) and r.get("auth_token_id") == token_id:
                dt = _parse_ts(r.get("timestamp") or r.get("created_at"))
                if dt and dt >= cutoff:
                    recent += 1
        if recent >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    def _log(token_id, workspace_id, status, error_code=None):
        logs = _ensure_logs()
        logs.append({
            "id": "req_" + uuid.uuid4().hex[:24],
            "endpoint": endpoint,
            "auth_token_id": token_id,
            "workspace_id": workspace_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
        })
        _save("request_logs.json", logs)

    if not isinstance(parent, dict):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "parent must be an object.", field="parent")

    ptype = parent.get("type")
    if ptype not in ("database", "page", "workspace"):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "parent.type must be one of 'database','page','workspace'.", field="parent.type")

    if not isinstance(properties, dict):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "properties must be an object.", field="properties")

    if icon is not None and not isinstance(icon, dict):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "icon must be an object.", field="icon")
    if cover is not None and not isinstance(cover, dict):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cover must be an object.", field="cover")
    if children is not None and not isinstance(children, list):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "children must be an array.", field="children")

    tokens = _load("auth_tokens.json")
    users = _load("notion_users.json")
    pages = _load("pages.json")
    dbs = _load("databases.json")
    blocks = _load("blocks.json")
    if not isinstance(tokens, list): tokens = []
    if not isinstance(users, list): users = []
    if not isinstance(pages, list): pages = []
    if not isinstance(dbs, list): dbs = []
    if not isinstance(blocks, list): blocks = []

    token = None
    bot_user = None
    for t in tokens:
        if not isinstance(t, dict) or t.get("status") != "active":
            continue
        ws = t.get("workspace_id")
        buid = t.get("bot_user_id")
        if not isinstance(ws, str) or not isinstance(buid, str):
            continue
        u = next((r for r in users if isinstance(r, dict) and r.get("id") == buid and r.get("workspace_id") == ws), None)
        if u and u.get("type") == "bot":
            token = t
            bot_user = u
            break
    if not token:
        _log(None, None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active authentication context available.")

    rl = _rate_limit_check(token.get("id"))
    if rl:
        _log(token.get("id"), token.get("workspace_id"), "error", rl["error"]["code"])
        return rl

    wsid = token.get("workspace_id")
    parent_database_id = None
    parent_page_id = None

    if ptype == "database":
        dbid = parent.get("database_id")
        if not isinstance(dbid, str) or not re.match(r"^db_01[0-9A-Z][0-9A-Z]+$", dbid):
            _log(token.get("id"), wsid, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent.database_id is invalid.", field="parent.database_id")
        db = next((d for d in dbs if isinstance(d, dict) and d.get("id") == dbid and d.get("workspace_id") == wsid), None)
        if not db:
            _log(token.get("id"), wsid, "error", "NOT_FOUND")
            return _err("NOT_FOUND", "Parent database not found.", database_id=dbid)
        parent_database_id = dbid
        schema = db.get("properties_schema") if isinstance(db.get("properties_schema"), dict) else {}
        # Validate only known keys; required-ness not modeled in schema reliably here.
        for k in properties.keys():
            if k not in schema:
                _log(token.get("id"), wsid, "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Property not in database schema.", field="properties", property=k)

    elif ptype == "page":
        pid = parent.get("page_id")
        if not isinstance(pid, str) or not re.match(r"^pg_01[0-9A-Z][0-9A-Z]+$", pid):
            _log(token.get("id"), wsid, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent.page_id is invalid.", field="parent.page_id")
        pp = next((p for p in pages if isinstance(p, dict) and p.get("id") == pid and p.get("workspace_id") == wsid), None)
        if not pp:
            _log(token.get("id"), wsid, "error", "NOT_FOUND")
            return _err("NOT_FOUND", "Parent page not found.", page_id=pid)
        if pp.get("status") == "trashed" or pp.get("trashed") is True:
            _log(token.get("id"), wsid, "error", "CONFLICT")
            return _err("CONFLICT", "Cannot create a page under a trashed page.", page_id=pid)
        parent_page_id = pid

    else:  # workspace
        # workspace_id optional in request; must match token workspace if provided
        if "workspace_id" in parent and parent.get("workspace_id") is not None and parent.get("workspace_id") != wsid:
            _log(token.get("id"), wsid, "error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Cannot create page in a different workspace.", field="parent.workspace_id")

    now = _now()
    new_id = "pg_" + uuid.uuid4().hex[:24]
    url = f"https://notion.local/{new_id}"

    # unique(workspace_id,url)
    if any(isinstance(p, dict) and p.get("workspace_id") == wsid and p.get("url") == url for p in pages):
        url = f"https://notion.local/{new_id}-{uuid.uuid4().hex[:6]}"

    row = {
        "id": new_id,
        "workspace_id": wsid,
        "parent_type": ptype,
        "parent_database_id": parent_database_id,
        "parent_page_id": parent_page_id,
        "properties": properties,
        "icon": icon,
        "cover": cover,
        "url": url,
        "archived": False,
        "trashed": False,
        "status": "active",
        "created_by_user_id": bot_user.get("id") if bot_user else None,
        "last_edited_by_user_id": bot_user.get("id") if bot_user else None,
        "created_at": now,
        "updated_at": now,
    }

    if not isinstance(row["created_by_user_id"], str) or not isinstance(row["last_edited_by_user_id"], str):
        _log(token.get("id"), wsid, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Token has no valid bot identity.")

    pages.append(row)
    _save("pages.json", pages)

    # Optional initial child blocks under page (parent_block_id null)
    created_blocks = []
    if isinstance(children, list) and children:
        allowed_types = {
            "paragraph", "heading_1", "heading_2", "heading_3",
            "bulleted_list_item", "numbered_list_item", "to_do", "toggle",
            "code", "quote", "callout", "divider", "image", "bookmark",
            "table", "table_row", "child_page", "child_database",
            "synced_block", "template", "unsupported"
        }
        sort_idx = 0
        for i, ch in enumerate(children):
            if not isinstance(ch, dict) or not isinstance(ch.get("type"), str) or ch.get("type") not in allowed_types or not isinstance(ch.get("content"), dict):
                _log(token.get("id"), wsid, "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid child block structure.", field=f"children[{i}]")
            bid = "blk_" + uuid.uuid4().hex[:24]
            brow = {
                "id": bid,
                "workspace_id": wsid,
                "page_id": new_id,
                "parent_block_id": None,
                "type": ch["type"],
                "content": ch["content"],
                "has_children": False,
                "children_sort": sort_idx,
                "archived": False,
                "status": "active",
                "created_by_user_id": row["created_by_user_id"],
                "last_edited_by_user_id": row["created_by_user_id"],
                "created_at": now,
                "updated_at": now,
            }
            sort_idx += 1
            blocks.append(brow)
            created_blocks.append(brow)
        _save("blocks.json", blocks)

    _log(token.get("id"), wsid, "success", None)
    return {"object": "page", "page": row, "children": created_blocks}

