            for t in auth_tokens:
                if t.get("id") == used_token["id"]:
                    t["last_used_at"] = now
                    t["updated_at"] = now
                    break
            _save("auth_tokens.json", auth_tokens)
        return payload

    # ---- authenticate (ambient): pick an active token that can serve the request
    for t in auth_tokens:
        if t.get("status") != "active":
            continue
        # token must belong to workspace with a bot user that exists and is bot
        bot_id = t.get("bot_user_id")
        wsid = t.get("workspace_id")
        bot = next((u for u in notion_users if u.get("id") == bot_id and u.get("workspace_id") == wsid and u.get("type") == "bot" and u.get("status") == "active"), None)
        if bot:
            used_token = t
            break

    if not used_token:
        status_code = "UNAUTHORIZED"
        return _log_and_return(_err("UNAUTHORIZED", "No active authentication context available."))

    wsid = used_token["workspace_id"]
    actor_user_id = used_token["bot_user_id"]

    # ---- simple rate limit / quota based on request_logs (per token)
    # 60 req/min, 10k req/day
    one_min_ago = (datetime.datetime.fromisoformat(now.replace("Z", "+00:00")) - datetime.timedelta(seconds=60)).isoformat().replace("+00:00", "Z")
    day_ago = (datetime.datetime.fromisoformat(now.replace("Z", "+00:00")) - datetime.timedelta(days=1)).isoformat().replace("+00:00", "Z")
    recent_min = 0
    recent_day = 0
    for r in request_logs:
        if r.get("auth_token_id") != used_token["id"]:
            continue
        ts = r.get("timestamp")
        if isinstance(ts, str):
            if ts >= one_min_ago:
                recent_min += 1
            if ts >= day_ago:
                recent_day += 1
    if recent_min >= 60:
        status_code = "RATE_LIMIT"
        return _log_and_return(_err("RATE_LIMIT", "Rate limit exceeded."))
    if recent_day >= 10000:
        status_code = "QUOTA_EXCEEDED"
        return _log_and_return(_err("QUOTA_EXCEEDED", "Daily quota exceeded."))

    # ---- validate inputs
    if not isinstance(database_id, str) or not re.match(r"^db_01H[0-9A-Z]+$", database_id):
        status_code = "VALIDATION_ERROR"
        return _log_and_return(_err("VALIDATION_ERROR", "database_id is malformed.", field="database_id"))

    if title is not None and not isinstance(title, list):
        status_code = "VALIDATION_ERROR"
        return _log_and_return(_err("VALIDATION_ERROR", "title must be an array.", field="title"))
    if description is not None and not isinstance(description, list):
        status_code = "VALIDATION_ERROR"
        return _log_and_return(_err("VALIDATION_ERROR", "description must be an array.", field="description"))
    if properties_schema is not None and not isinstance(properties_schema, dict):
        status_code = "VALIDATION_ERROR"
        return _log_and_return(_err("VALIDATION_ERROR", "properties_schema must be an object.", field="properties_schema"))
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived"):
            status_code = "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "status must be one of: active, archived.", field="status"))

    if all(v is None for v in (title, description, properties_schema, status)):
        status_code = "VALIDATION_ERROR"
        return _log_and_return(_err("VALIDATION_ERROR", "At least one of title, description, properties_schema, status must be provided."))

    # ---- find database in workspace
    db = next((d for d in databases if d.get("id") == database_id and d.get("workspace_id") == wsid), None)
    if not db:
        status_code = "NOT_FOUND"
        return _log_and_return(_err("NOT_FOUND", "Database not found."))

    # ---- enforce lifecycle transitions
    if status is not None and status != db.get("status"):
        transitions = {"active": ["archived"], "archived": ["active"]}
        cur = db.get("status")
        if cur not in transitions or status not in transitions[cur]:
            status_code = "INVALID_TRANSITION"
            return _log_and_return(_err("INVALID_TRANSITION", f"Cannot transition database status from {cur} to {status}.", from_status=cur, to_status=status))

    # ---- schema update validation: must not invalidate existing pages.properties
    # Minimal, practical checks:
    # - property keys are strings
    # - removing an existing property key is rejected if any page in the database has it (to avoid invalidation)
    # - changing an existing property's declared type is rejected if pages store incompatible existing values
    #   (we infer stored values by looking for a "type" key in property value objects when present)
    def _schema_type_of(prop_schema_obj):
        if isinstance(prop_schema_obj, dict):
            t = prop_schema_obj.get("type")
            return t if isinstance(t, str) else None
        return None

    if properties_schema is not None:
        # interpret as full replacement if it has keys beyond partial update; allow partial by merging
        if not all(isinstance(k, str) for k in properties_schema.keys()):
            status_code = "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "properties_schema keys must be strings."))

        old_schema = db.get("properties_schema")
        if not isinstance(old_schema, dict):
            old_schema = {}

        # merge (Notion-like update semantics)
        new_schema = copy.deepcopy(old_schema)
        for k, v in properties_schema.items():
            if v is None:
                # treat explicit null as an attempt to remove property
                if k in new_schema:
                    del new_schema[k]
            else:
                new_schema[k] = v

        # Reject if it removes keys that are in use
        removed_keys = set(old_schema.keys()) - set(new_schema.keys())

        # get pages in this database
        db_pages = [p for p in pages if p.get("workspace_id") == wsid and p.get("parent_type") == "database" and p.get("parent_database_id") == database_id]
        for rk in removed_keys:
            for p in db_pages:
                props = p.get("properties")
                if isinstance(props, dict) and rk in props:
                    status_code = "CONFLICT"
                    return _log_and_return(_err("CONFLICT", f"Cannot remove property '{rk}' because existing pages contain values for it.", property=rk))

        # Reject if it changes type incompatibly for existing values
        for key in set(old_schema.keys()).intersection(new_schema.keys()):
            old_t = _schema_type_of(old_schema.get(key))
            new_t = _schema_type_of(new_schema.get(key))
            if old_t and new_t and old_t != new_t:
                # check stored property values: if property value has a 'type', ensure it matches new type
                for p in db_pages:
                    props = p.get("properties")
                    if not isinstance(props, dict) or key not in props:
                        continue
                    val = props.get(key)
                    if isinstance(val, dict) and isinstance(val.get("type"), str):
                        if val.get("type") != new_t:
                            status_code = "CONFLICT"
                            return _log_and_return(_err(
                                "CONFLICT",
                                f"Cannot change type of property '{key}' from '{old_t}' to '{new_t}' because existing page properties are incompatible.",
                                property=key, from_type=old_t, to_type=new_t
                            ))
                # if no typed values, still reject to be safe (schema evolution without migration)
                status_code = "CONFLICT"
                return _log_and_return(_err(
                    "CONFLICT",
                    f"Cannot change type of property '{key}' from '{old_t}' to '{new_t}' without migration.",
                    property=key, from_type=old_t, to_type=new_t
                ))

        # apply schema
        db["properties_schema"] = new_schema

    # ---- apply other mutations
    changed = False
    if title is not None:
        db["title"] = title
        changed = True
    if description is not None:
        db["description"] = description
        changed = True
    if properties_schema is not None:
        changed = True
    if status is not None and status != db.get("status"):
        db["status"] = status
        changed = True

    if not changed:
        # No success without effect
        status_code = "CONFLICT"
        return _log_and_return(_err("CONFLICT", "Update would make no changes."))

    # ---- audit fields
    db["last_edited_by_user_id"] = actor_user_id
    db["updated_at"] = now

    _save("databases.json", databases)

    status_code = "ok"
    return _log_and_return({
        "object": "database",
        "data": db
    })

def API_retrieve_a_database(database_id, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0108000" if __import__("os").path.isdir("./environment_mix/0108000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    auth_tokens = _load("auth_tokens.json")
    notion_users = _load("notion_users.json")
    databases = _load("databases.json")
    request_logs = _load("request_logs.json")

    endpoint = "API-retrieve-a-database"
    used_token = None
    status_code = "ok"

    def _log_and_return(payload):
        nonlocal request_logs, auth_tokens, used_token, status_code
        latency_ms = int((time.time() - t0) * 1000)
        request_logs.append({
            "id": "req_" + uuid.uuid4().hex[:24],
            "endpoint": endpoint,
            "auth_token_id": used_token["id"] if used_token else None,
            "workspace_id": used_token["workspace_id"] if used_token else None,
            "status": status_code,
            "latency_ms": latency_ms,
            "timestamp": now
        })
        _save("request_logs.json", request_logs)
        if used_token:
            for t in auth_tokens:
                if t.get("id") == used_token["id"]:
                    t["last_used_at"] = now
                    t["updated_at"] = now
                    break
            _save("auth_tokens.json", auth_tokens)
        return payload

    # authenticate ambient
    for t in auth_tokens:
        if t.get("status") != "active":
            continue
        bot_id = t.get("bot_user_id")
        wsid = t.get("workspace_id")
        bot = next((u for u in notion_users if u.get("id") == bot_id and u.get("workspace_id") == wsid and u.get("type") == "bot" and u.get("status") == "active"), None)
        if bot:
            used_token = t
            break

    if not used_token:
        status_code = "UNAUTHORIZED"
        return _log_and_return(_err("UNAUTHORIZED", "No active authentication context available."))

    wsid = used_token["workspace_id"]

    # rate limit / quota (same as other endpoint)
    one_min_ago = (datetime.datetime.fromisoformat(now.replace("Z", "+00:00")) - datetime.timedelta(seconds=60)).isoformat().replace("+00:00", "Z")
    day_ago = (datetime.datetime.fromisoformat(now.replace("Z", "+00:00")) - datetime.timedelta(days=1)).isoformat().replace("+00:00", "Z")
    recent_min = 0
    recent_day = 0
    for r in request_logs:
        if r.get("auth_token_id") != used_token["id"]:
            continue
        ts = r.get("timestamp")
        if isinstance(ts, str):
            if ts >= one_min_ago:
                recent_min += 1
            if ts >= day_ago:
                recent_day += 1
    if recent_min >= 60:
        status_code = "RATE_LIMIT"
        return _log_and_return(_err("RATE_LIMIT", "Rate limit exceeded."))
    if recent_day >= 10000:
        status_code = "QUOTA_EXCEEDED"
        return _log_and_return(_err("QUOTA_EXCEEDED", "Daily quota exceeded."))

    # validate
    if not isinstance(database_id, str) or not re.match(r"^db_01H[0-9A-Z]+$", database_id):
        status_code = "VALIDATION_ERROR"
        return _log_and_return(_err("VALIDATION_ERROR", "database_id is malformed.", field="database_id"))

    db = next((d for d in databases if d.get("id") == database_id and d.get("workspace_id") == wsid), None)
    if not db:
        status_code = "NOT_FOUND"
        return _log_and_return(_err("NOT_FOUND", "Database not found."))

    # business rule: return only if not archived (default behavior here)
    if db.get("status") == "archived":
        status_code = "NOT_FOUND"
        return _log_and_return(_err("NOT_FOUND", "Database not found."))

    status_code = "ok"
    return _log_and_return({
        "object": "database",
        "data": db
    })

def API_retrieve_a_page_property(page_id, property_id, start_cursor=None, page_size=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0108000" if __import__("os").path.isdir("./environment_mix/0108000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(token_id, workspace_id, status, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex[:24],
            "endpoint": "API-retrieve-a-page-property",
            "auth_token_id": token_id,
            "workspace_id": workspace_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now()
        })
        _save("request_logs.json", logs)

    def _rate_limit(token_id):
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path) or token_id is None:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("auth_token_id") != token_id:
                continue
            ts = r.get("timestamp") or r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                recent += 1
        if recent >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    # Validate
    if not isinstance(page_id, str) or not re.match(r"^pg_01H[0-9A-Z]+$", page_id):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_id is invalid.", field="page_id")
    if not isinstance(property_id, str) or not property_id:
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "property_id is required.", field="property_id")
    if start_cursor is not None and not isinstance(start_cursor, str):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "start_cursor must be a string.", field="start_cursor")
    if page_size is None:
        page_size = 100
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_size must be between 1 and 100.", field="page_size")

    tokens = _load("auth_tokens.json")
    users = _load("notion_users.json")
    pages = _load("pages.json")
    if not isinstance(tokens, list):
        tokens = []
    if not isinstance(users, list):
        users = []
    if not isinstance(pages, list):
        pages = []

    page = next((p for p in pages if isinstance(p, dict) and p.get("id") == page_id), None)
    if page is None:
        _log(None, None, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Page not found.")

    # Auth: any active token usable for page.workspace_id
    user_by_id = {u.get("id"): u for u in users if isinstance(u, dict) and isinstance(u.get("id"), str)}
    token = None
    for t in tokens:
        if not isinstance(t, dict) or t.get("status") != "active":
            continue
        if t.get("workspace_id") != page.get("workspace_id"):
            continue
        buid = t.get("bot_user_id")
        wsid = t.get("workspace_id")
        u = user_by_id.get(buid) if isinstance(buid, str) else None
        if not u or u.get("workspace_id") != wsid or u.get("type") != "bot" or u.get("status") != "active":
            continue
        token = t
        break
    if token is None:
        _log(None, page.get("workspace_id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Integration token missing or invalid.")

    rl = _rate_limit(token.get("id"))
    if rl:
        _log(token.get("id"), token.get("workspace_id"), "error", "RATE_LIMIT")
        return rl

    # Touch token usage
    now = _now()
    for t in tokens:
        if isinstance(t, dict) and t.get("id") == token.get("id"):
            t["last_used_at"] = now
            t["updated_at"] = now
            break
    _save("auth_tokens.json", tokens)

    # Enforce trashed visibility: unless explicitly allowed via _extra
    allow_trashed = bool(_extra.get("include_trashed")) or bool(_extra.get("allow_trashed"))
    if page.get("status") == "trashed" and not allow_trashed:
        _log(token.get("id"), token.get("workspace_id"), "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Page not found.")

    props = page.get("properties")
    if not isinstance(props, dict) or property_id not in props:
        _log(token.get("id"), token.get("workspace_id"), "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Property not found on page.", property_id=property_id)

    prop_val = props.get(property_id)

    # Support simple pagination for list-like stored structures (relation-like/rollup-like)
    # If property is dict with key "results" as list: paginate that; else if it's list: paginate list; else return as-is.
    items = None
    if isinstance(prop_val, dict) and isinstance(prop_val.get("results"), list):
        items = prop_val.get("results")
    elif isinstance(prop_val, list):
        items = prop_val

    if items is None:
        _log(token.get("id"), token.get("workspace_id"), "ok", None)
        return {"object": "property_item", "property_id": property_id, "value": prop_val}

    start_index = 0
    if start_cursor:
        try:
            start_index = int(start_cursor)
            if start_index < 0:
                raise ValueError()
        except Exception:
            _log(token.get("id"), token.get("workspace_id"), "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "start_cursor is invalid.", field="start_cursor")

    sliced = items[start_index:start_index + page_size]
    next_cursor = str(start_index + page_size) if (start_index + page_size) < len(items) else None

    _log(token.get("id"), token.get("workspace_id"), "ok", None)
    return {
        "object": "list",
        "property_id": property_id,
        "results": sliced,
        "next_cursor": next_cursor,
        "has_more": next_cursor is not None,
        "total": len(items)
    }

def API_retrieve_a_comment(comment_id, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0108000" if __import__("os").path.isdir("./environment_mix/0108000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "API-retrieve-a-comment"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _rate_limit_check(token_id):
        if not token_id:
            return None
        logs = _ensure_logs()
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs:
            if isinstance(r, dict) and r.get("auth_token_id") == token_id:
                dt = _parse_ts(r.get("timestamp") or r.get("created_at"))
                if dt and dt >= cutoff:
                    recent += 1
        if recent >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    def _log(token_id, workspace_id, status, error_code=None):
        logs = _ensure_logs()
        logs.append({
            "id": "req_" + uuid.uuid4().hex[:24],
            "endpoint": endpoint,
            "auth_token_id": token_id,
            "workspace_id": workspace_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now()
        })
        _save("request_logs.json", logs)

    if not isinstance(comment_id, str) or not re.match(r"^cmt_[0-9A-Za-z]+$", comment_id):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "comment_id is invalid.", field="comment_id")

    comments = _load("comments.json")
    tokens = _load("auth_tokens.json")
    users = _load("notion_users.json")
    if not isinstance(comments, list): comments = []
    if not isinstance(tokens, list): tokens = []
    if not isinstance(users, list): users = []

    token = None
    for t in tokens:
        if not isinstance(t, dict) or t.get("status") != "active":
            continue
        ws = t.get("workspace_id")
        buid = t.get("bot_user_id")
        if not isinstance(ws, str) or not isinstance(buid, str):
            continue
        u = next((r for r in users if isinstance(r, dict) and r.get("id") == buid and r.get("workspace_id") == ws), None)
        if u and u.get("type") == "bot":
            token = t
            break
    if not token:
        _log(None, None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active authentication context available.")

    rl = _rate_limit_check(token.get("id"))
    if rl:
        _log(token.get("id"), token.get("workspace_id"), "error", rl["error"]["code"])
        return rl

    wsid = token.get("workspace_id")
    c = next((x for x in comments if isinstance(x, dict) and x.get("id") == comment_id), None)
    if not c:
        _log(token.get("id"), wsid, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Comment does not exist.", comment_id=comment_id)
    if c.get("workspace_id") != wsid:
        _log(token.get("id"), wsid, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Integration does not have access to the comment.")

    # Redaction policy: if deleted, redact rich_text
    out = dict(c)
    if out.get("status") == "deleted":
        out["rich_text"] = []

    _log(token.get("id"), wsid, "success", None)
    return {"object": "comment", "comment": out}

def API_create_a_comment(page_id, rich_text, discussion_id=None, parent_comment_id=None, anchor_block_id=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0108000" if __import__("os").path.isdir("./environment_mix/0108000") else "/app/database")
