    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "API-create-a-comment"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _rate_limit_check(token_id):
        if not token_id:
            return None
        logs = _ensure_logs()
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs:
            if isinstance(r, dict) and r.get("auth_token_id") == token_id:
                dt = _parse_ts(r.get("timestamp") or r.get("created_at"))
                if dt and dt >= cutoff:
                    recent += 1
        if recent >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    def _log(token_id, workspace_id, status, error_code=None):
        logs = _ensure_logs()
        logs.append({
            "id": "req_" + uuid.uuid4().hex[:24],
            "endpoint": endpoint,
            "auth_token_id": token_id,
            "workspace_id": workspace_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
        })
        _save("request_logs.json", logs)

    if not isinstance(page_id, str) or not re.match(r"^pg_[0-9A-Za-z]+$", page_id):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_id is invalid.", field="page_id")
    if not isinstance(rich_text, list):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "rich_text must be an array.", field="rich_text")
    if parent_comment_id is not None and (not isinstance(parent_comment_id, str) or not re.match(r"^cmt_[0-9A-Za-z]+$", parent_comment_id)):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "parent_comment_id is invalid.", field="parent_comment_id")
    if anchor_block_id is not None and (not isinstance(anchor_block_id, str) or not re.match(r"^blk_[0-9A-Za-z]+$", anchor_block_id)):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "anchor_block_id is invalid.", field="anchor_block_id")
    if discussion_id is not None and not isinstance(discussion_id, str):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "discussion_id must be a string.", field="discussion_id")

    tokens = _load("auth_tokens.json")
    users = _load("notion_users.json")
    pages = _load("pages.json")
    blocks = _load("blocks.json")
    comments = _load("comments.json")
    if not isinstance(tokens, list): tokens = []
    if not isinstance(users, list): users = []
    if not isinstance(pages, list): pages = []
    if not isinstance(blocks, list): blocks = []
    if not isinstance(comments, list): comments = []

    token = None
    bot_user = None
    for t in tokens:
        if not isinstance(t, dict) or t.get("status") != "active":
            continue
        ws = t.get("workspace_id")
        buid = t.get("bot_user_id")
        if not isinstance(ws, str) or not isinstance(buid, str):
            continue
        u = next((r for r in users if isinstance(r, dict) and r.get("id") == buid and r.get("workspace_id") == ws), None)
        if u and u.get("type") == "bot":
            token = t
            bot_user = u
            break
    if not token:
        _log(None, None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active authentication context available.")
    if not bot_user:
        _log(token.get("id"), token.get("workspace_id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Token has no valid bot identity.")

    rl = _rate_limit_check(token.get("id"))
    if rl:
        _log(token.get("id"), token.get("workspace_id"), "error", rl["error"]["code"])
        return rl

    wsid = token.get("workspace_id")
    page = next((p for p in pages if isinstance(p, dict) and p.get("id") == page_id and p.get("workspace_id") == wsid), None)
    if not page:
        _log(token.get("id"), wsid, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Page not found.", page_id=page_id)
    if page.get("status") == "trashed" or page.get("trashed") is True:
        _log(token.get("id"), wsid, "error", "CONFLICT")
        return _err("CONFLICT", "Cannot comment on a trashed page.", page_id=page_id)

    if anchor_block_id is not None:
        blk = next((b for b in blocks if isinstance(b, dict) and b.get("id") == anchor_block_id and b.get("workspace_id") == wsid), None)
        if not blk:
            _log(token.get("id"), wsid, "error", "NOT_FOUND")
            return _err("NOT_FOUND", "Anchor block not found.", block_id=anchor_block_id)
        if blk.get("page_id") != page_id:
            _log(token.get("id"), wsid, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "anchor_block_id must reference a block on the same page.", field="anchor_block_id")

    if parent_comment_id is not None:
        pc = next((c for c in comments if isinstance(c, dict) and c.get("id") == parent_comment_id and c.get("workspace_id") == wsid), None)
        if not pc:
            _log(token.get("id"), wsid, "error", "NOT_FOUND")
            return _err("NOT_FOUND", "Parent comment not found.", comment_id=parent_comment_id)
        if pc.get("page_id") != page_id:
            _log(token.get("id"), wsid, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_comment_id must reference a comment on the same page.", field="parent_comment_id")
        # If replying, inherit discussion_id if not provided
        if discussion_id is None and isinstance(pc.get("discussion_id"), str):
            discussion_id = pc.get("discussion_id")

    if discussion_id is None:
        discussion_id = "dsc_" + uuid.uuid4().hex[:24]

    now = _now()
    new_id = "cmt_" + uuid.uuid4().hex[:24]
    row = {
        "id": new_id,
        "workspace_id": wsid,
        "page_id": page_id,
        "discussion_id": discussion_id,
        "parent_comment_id": parent_comment_id,
        "anchor_block_id": anchor_block_id,
        "rich_text": rich_text,
        "created_by_user_id": bot_user.get("id"),
        "status": "published",
        "created_at": now,
        "updated_at": now,
    }
    comments.append(row)
    _save("comments.json", comments)

    _log(token.get("id"), wsid, "success", None)
    return {"object": "comment", "comment": row}
